test("HTML の要素は、外接矩形ではなく変形を効かせる前のレイアウトの幅と高さで測れる", () => {
  const element = globalThis.document.createElement("div");
  stubBounds(element, { left: 10, top: 20, width: 150, height: 130 });
  stubLayoutSize(element, { width: 100, height: 60 });

  expect(ElementMeasure.layoutSizeOf(element)).toEqual(
    Option.some({ width: 100, height: 60 }),
  );
});

test("HTML の要素でない SVG はレイアウトの大きさを測れない", () => {
  const element = globalThis.document.createElementNS(
    "http://www.w3.org/2000/svg",
    "svg",
  );

  expect(ElementMeasure.layoutSizeOf(element)).toEqual(Option.none);
});

function stubbedElement(): Element {
  const element = globalThis.document.createElement("div");
  stubBounds(element, { left: 10, top: 20, width: 30, height: 40 });
  return element;
}

test("描かれている要素の矩形を client 座標の位置と大きさで返す", () => {
  const bounds = ElementMeasure.boundsOf(stubbedElement());

  expect(bounds).toEqual({ left: 10, top: 20, width: 30, height: 40 });
});

test("名前で指したものが収まる倍率と位置になる", async () => {
  // 等倍・原点で描かれている 1552 × 352 を、余白込みの 1600 × 400 として 0.5 倍で収める
  drawNamed("home", { left: 100, top: 50, width: 1552, height: 352 });
  render(<FitHarness names={["home"]} />);

  await pressFit();

  expect(transform()).toBe("translate(12px, 212px) scale(0.5)");
});

test("回った要素は、レイアウトの大きさに倍率を掛けた矩形を外接矩形の中心に置いたものになる", () => {
  /*
   * 外接矩形 (100, 40) 300x200 の中心は (250, 140)。回る前の大きさ 100x40 を 2 倍した
   * 200x80 をそこへ置く。外接矩形の大きさからは導けない大きさにしてある。
   */
  const target = drawNamed("card", {
    left: 100,
    top: 40,
    width: 300,
    height: 200,
  });
  stubLayoutSize(target, { width: 100, height: 40 });

  render(
    <BoundsProbe
      target={Option.some("card")}
      rotation={30}
      view={{ ...CanvasView.create(), scale: 2 }}
    />,
  );

  // 器の左上（10, 20）を原点に置き直すので、(150, 100) は (140, 80) になる
  expect(screen.getByTestId("bounds").textContent).toBe("140,80,200,80");
});
